class DirectContextRetrievalTests(TestCase):
    """Verify the new direct-context retrieval returns the right portfolio data."""

    @classmethod
    def setUpTestData(cls):
        # Seed a small, deterministic portfolio so the retrieval tests can
        # assert counts and active filters without depending on a live fixture.
        from project.models import Category, Project
        from studio.models import Service, StudioSettings

        cat = Category.objects.create(
            name="Design", slug="design", description="Creative services",
            is_active=True,
        )
        Project.objects.create(
            title="Published project", slug="published-project",
            category=cat, description="A published project", year=2025,
            status=True, active_status=True,
        )
        Project.objects.create(
            title="Archived project", slug="archived-project",
            category=cat, description="Archived", year=2024,
            status=True, active_status=False,
        )
        Service.objects.create(
            title="Consulting", slug="consulting", description="Strategy",
            is_active=True,
        )
        StudioSettings.objects.create(
            name="Hectic Lab", tagline="Portfolio studio",
            about="Creative studio", description="—", vision="Design and strategy",
        )

    def test_get_public_projects_filters_active(self):
        projects = list(get_public_projects())
        self.assertGreaterEqual(len(projects), 1)
        # Active projects only
        for p in projects:
            self.assertTrue(p.status)
            self.assertTrue(p.active_status)
            self.assertTrue(p.category.is_active)
            # The domain model stores the title in the `title` column.
            self.assertTrue(p.title)

    def test_get_public_categories(self):
        categories = list(get_public_categories())
        self.assertGreaterEqual(len(categories), 1)
        for c in categories:
            self.assertTrue(c.is_active)

    def test_get_public_services(self):
        services = list(get_public_services())
        self.assertGreaterEqual(len(services), 1)
        for s in services:
            self.assertTrue(s.is_active)

    def test_get_public_studio(self):
        studio = get_public_studio()
        self.assertIsNotNone(studio)
        self.assertTrue(studio.name)


class PromptConstructionTests(TestCase):
    """Verify the direct-context prompt is concise and contains the question."""

    def test_prompt_includes_question_and_context(self):
        prompt = build_gemini_context(
            question="What projects do you have?",
            history=[],
        )
        self.assertIn("What projects do you have?", prompt)
        self.assertIn("PORTFOLIO CONTEXT", prompt)
        # History is bounded so long conversations never bloat the prompt.
        self.assertLessEqual(
            prompt.count("PREVIOUS CONVERSATION"), 1
        )


class GeminiSingletonAndModelSelectionTests(TestCase):
    """Verify one client is reused and the fastest registered model is picked."""

    def setUp(self):
        super().setUp()
        # Reset the singletons before each test.
        import ai_agent.utils as u

        with u._GEMINI_CLIENT_LOCK:
            u._GEMINI_CLIENT = None
        with u._GEMINI_CHAT_MODEL_LOCK:
            u._GEMINI_CHAT_MODEL = None

    @override_settings(GEMINI_API_KEY="test-key")
    @patch("ai_agent.utils.genai.Client")
    def test_get_gemini_client_returns_singleton(self, mock_client_cls):
        import ai_agent.utils as u

        c1 = get_gemini_client()
        c2 = get_gemini_client()
        self.assertIs(c1, c2)
        self.assertEqual(mock_client_cls.call_count, 1)

    @override_settings(GEMINI_API_KEY="test-key", GEMINI_CHAT_MODEL="")
    def test_select_fastest_flash_model(self):
        """Default GEMINI_CHAT_MODEL empty / missing resolves to the ladder's
        fastest model (lowest thinking overhead, Flash)."""
        import ai_agent.utils as u

        # Reset any singleton value left by other tests in this class.
        with u._GEMINI_CHAT_MODEL_LOCK:
            u._GEMINI_CHAT_MODEL = None
        # Clear the cached model name so the ladder is re-evaluated.
        u._GEMINI_CHAT_MODEL = None
        self.assertEqual(
            u._select_gemini_chat_model(), "gemini-3.1-flash-preview"
        )

    @override_settings(GEMINI_API_KEY="test-key")
    def test_select_fastest_model_from_ladder(self):
        """Each ladder candidate is returned when passed as GEMINI_CHAT_MODEL."""
        import ai_agent.utils as u

        for candidate in _GEMINI_MODEL_CANDIDATES:
            with u._GEMINI_CHAT_MODEL_LOCK:
                u._GEMINI_CHAT_MODEL = None
            with override_settings(
                GEMINI_API_KEY="test-key", GEMINI_CHAT_MODEL=candidate
            ):
                self.assertEqual(
                    u._select_gemini_chat_model(), candidate
                )

    @override_settings(GEMINI_API_KEY="test-key", GEMINI_CHAT_MODEL="gemini-3.8-flash")
    def test_model_selection_returns_unknown_config_as_is(self):
        """A model name that is not a ladder candidate passes through."""
        import ai_agent.utils as u

        with u._GEMINI_CHAT_MODEL_LOCK:
            u._GEMINI_CHAT_MODEL = None
        self.assertEqual(u._select_gemini_chat_model(), "gemini-3.8-flash")

    @override_settings(GEMINI_API_KEY="test-key", AI_CHAT_CACHE_ENABLED=True)
    def test_cache_hit_skips_gemini(self):
        import ai_agent.utils as u

        with u._GEMINI_CLIENT_LOCK:
            u._GEMINI_CLIENT = None

        with patch("ai_agent.utils.genai.Client") as mock_client_cls:
            # Make the mocked Gemini return a stable, pickleable answer.
            mock_client_instance = mock_client_cls.return_value
            mock_client_instance.models.generate_content.return_value.text = (
                "Mocked assistant answer."
            )

            # First call: cache miss -> fills DB cache.
            generate_chat_response(
                question="What is Hectic Lab?",
                history=[],
            )
            self.assertEqual(mock_client_cls.call_count, 1)

            # Second call: same question -> cache hit -> no Gemini call.
            mock_client_cls.reset_mock()
            generate_chat_response(
                question="What is Hectic Lab?",
                history=[],
            )
            self.assertEqual(mock_client_cls.call_count, 0)

    @override_settings(
        GEMINI_API_KEY="test-key",
        GEMINI_CHAT_FALLBACK_MODEL="fallback-model",
        AI_CHAT_CACHE_ENABLED=False,
    )
    def test_temporary_provider_error_uses_fallback_model(self):
        with (
            patch(
                "ai_agent.utils._select_gemini_chat_model",
                return_value="primary-model",
            ),
            patch("ai_agent.utils.get_gemini_client") as mock_get_client,
        ):
            client = mock_get_client.return_value
            client.models.generate_content.side_effect = [
                genai_errors.APIError(503, {}),
                Mock(text="Fallback answer."),
            ]

            answer = generate_chat_response(
                question="A unique fallback test question",
                context_prompt="Already built prompt",
            )

        self.assertEqual(answer, "Fallback answer.")
        self.assertEqual(
            [
                call.kwargs["model"]
                for call in client.models.generate_content.call_args_list
            ],
            ["primary-model", "fallback-model"],
        )
        self.assertEqual(
            client.models.generate_content.call_args.kwargs["contents"],
            "Already built prompt",
        )

    @override_settings(
        GEMINI_API_KEY="test-key",
        GEMINI_CHAT_FALLBACK_MODEL="fallback-model",
        AI_CHAT_CACHE_ENABLED=False,
    )
    def test_non_temporary_provider_error_does_not_use_fallback(self):
        with (
            patch(
                "ai_agent.utils._select_gemini_chat_model",
                return_value="primary-model",
            ),
            patch("ai_agent.utils.get_gemini_client") as mock_get_client,
        ):
            client = mock_get_client.return_value
            client.models.generate_content.side_effect = genai_errors.APIError(400, {})

            with self.assertRaises(genai_errors.APIError):
                generate_chat_response(
                    question="A unique invalid request test",
                    context_prompt="Already built prompt",
                )

        self.assertEqual(client.models.generate_content.call_count, 1)

    @override_settings(GEMINI_API_KEY="test-key", AI_CHAT_CACHE_ENABLED=True)
    def test_cache_key_is_content_not_hash(self):
        import ai_agent.utils as u

        with u._GEMINI_CLIENT_LOCK:
            u._GEMINI_CLIENT = None

        a = "hello world"
        b = "hello world"  # same content -> same key
        c = "hello cruel world"  # different content -> different key

        self.assertEqual(a, b)
        self.assertNotEqual(a, c)
        # Build explicit cache keys and verify content is part of the key.
        ka = u._make_cache_key(
            policy="hectic_lab_assistant", question=a, ttl=300)
        kb = u._make_cache_key(
            policy="hectic_lab_assistant", question=b, ttl=300)
        kc = u._make_cache_key(
            policy="hectic_lab_assistant", question=c, ttl=300)

        self.assertEqual(ka, kb)  # identical content -> identical key
        self.assertNotEqual(kc, ka)  # different content -> different key
        # The policy and TTL are part of the key.
        self.assertIn("hectic_lab_assistant", ka)
        self.assertIn("#300", ka)
        # Content is hashed, so the literal question string is not in the key.
        self.assertNotIn("hello world", kc[:30])

    @override_settings(GEMINI_API_KEY="test-key", AI_CHAT_CACHE_ENABLED=True)
    def test_cache_key_differs_for_rephrased_question(self):
        import ai_agent.utils as u

        with u._GEMINI_CLIENT_LOCK:
            u._GEMINI_CLIENT = None

        a = "What projects do you have?"
        b = "Tell me about the projects you have"  # rephrased, same intent

        ka = u._make_cache_key(
            policy="hectic_lab_assistant", question=a, ttl=300)
        kb = u._make_cache_key(
            policy="hectic_lab_assistant", question=b, ttl=300)

        # Rephrased questions produce distinct cache keys.
        self.assertNotEqual(ka, kb)


class PortfolioChatViewTests(TestCase):
    @override_settings(
        AI_CHAT_CACHE_ENABLED=True,
        AI_CHAT_CACHE_TTL_SECONDS=300,
    )
    def test_post_generates_answer_with_cache_enabled(self):
        request = APIRequestFactory().post(
            "/api/v1/assistant/chat/",
            {"message": "What projects do you have?"},
            format="json",
        )

        with (
            patch.object(chat_views.PortfolioChatView, "throttle_classes", []),
            patch(
                "ai_agent.views.build_gemini_context",
                return_value="portfolio context",
            ),
            patch(
                "ai_agent.views.generate_chat_response",
                return_value="Here are our projects.",
            ) as mock_generate_response,
            patch.object(
                chat_views.PortfolioChatView,
                "_build_project_sources",
                return_value=[],
            ),
        ):
            response = chat_views.PortfolioChatView.as_view()(request)

        self.assertEqual(response.status_code, 200)
        self.assertEqual(response.data["answer"], "Here are our projects.")
        self.assertEqual(
            mock_generate_response.call_args.kwargs["context_prompt"],
            "portfolio context",
        )
        self.assertEqual(
            ChatMessage.objects.filter(role="user").count(),
            1,
        )
        self.assertEqual(
            ChatMessage.objects.filter(role="assistant").count(),
            1,
        )

    @override_settings(AI_CHAT_CACHE_ENABLED=False)
    def test_temporary_provider_error_returns_retryable_503(self):
        request = APIRequestFactory().post(
            "/api/v1/assistant/chat/",
            {"message": "A unique provider error test"},
            format="json",
        )

        with (
            patch.object(chat_views.PortfolioChatView, "throttle_classes", []),
            patch(
                "ai_agent.views.build_gemini_context",
                return_value="portfolio context",
            ),
            patch(
                "ai_agent.views.generate_chat_response",
                side_effect=genai_errors.APIError(503, {}),
            ),
        ):
            response = chat_views.PortfolioChatView.as_view()(request)

        self.assertEqual(response.status_code, 503)
        self.assertEqual(response.data["code"], "AI_PROVIDER_UNAVAILABLE")
        self.assertEqual(response["Retry-After"], "5")
